ft={'1':np.ones_like(t),'t':t,'1/t':1/t,'sqrt t':np.sqrt(t),'log t':np.log(t),'exp(-t)':np.exp(-t),'t^2':t**2,'exp(0.1t)':np.exp(0.1*t),'exp(-0.2t)':np.exp(-0.2*t),'log(1+t)':np.log1p(t),'1/(1+t)':1/(1+t),'sin t':np.sin(t),'cos t':np.cos(t)}
feats={}
for (pn,pv),(tn,tv) in itertools.product(gP.items(),ft.items()):
    feats[pn+'*'+tn]=pv*tv
def score(cols):
    X=np.column_stack(cols); c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
    return np.mean(r**2)/np.var(y)
